collaboration=json.loads((HERE/'collaboration.json').read_text())
journey_stages=[]
for chat,stage in zip(chats,collaboration['stages'],strict=True):
    n,title,time,goal,desc,pr,path=chat
    assert title==stage['chat']
    steps=[]
    evidence=[]
    for i,step in enumerate(stage['steps'],1):
        links=' · '.join(f'<a href="{REPO}/pull/{p}">PR #{p} ↗</a>' for p in step['pr'])
        steps.append(f'''<article class="ownership-step"><div class="step-heading"><span>{n}.{i}</span><h4>{e(step['title'])}</h4><small>{links}</small></div><div class="ownership-grid"><div class="ai-column"><b>AI 可以做 · 实际执行</b><p>{e(step['ai'])}</p></div><div class="human-column"><b>我做了什么 · 判断与纠偏</b><p>{e(step['human'])}</p></div><div class="limit-column"><b>AI 不能独立完成</b><p>{e(step['boundary'])}</p></div></div></article>''')
        for item in step['evidence']:
            when=datetime.fromisoformat(item['timestamp'].replace('Z','+00:00')).astimezone(timezone(timedelta(hours=8))).strftime('%m.%d %H:%M:%S')
            evidence.append(f'<figure class="instruction"><figcaption>{e(step["title"])} · {when} 北京时间</figcaption><blockquote>“{e(item["quote"])}”</blockquote></figure>')
    journey_stages.append(f'''<article class="collaboration-stage"><header class="collaboration-header"><span class="timeline-marker">{n}</span><div class="timeline-time">{time}<small>北京时间 · 会话建立</small></div><div><h3>{e(title)}</h3><p>{goal}</p></div></header>{''.join(steps)}<details class="instruction-records"><summary>查看我在会话中的实际指令 <span>{len(evidence)} 条片段</span></summary>{''.join(evidence)}<p class="caption">来自本会话原始用户消息，保留原话片段与时间；AI 执行结果对照对应 PR。边界栏是基于这些决定和失败的归纳。</p></details></article>''')
timeline=''.join(journey_stages)
pr_rows=''
for p in HISTORY['pull_requests']:
    sha=p['mergeCommit']['oid']; merged=datetime.fromisoformat(p['mergedAt'].replace('Z','+00:00')).astimezone(timezone(timedelta(hours=8))).strftime('%m.%d %H:%M')
    pr_rows+=f'<tr><td><a href="{p["url"]}">#{p["number"]} ↗</a></td><td>{e(p["title"])}</td><td><a href="{REPO}/commit/{sha}"><code>{sha[:7]}</code></a></td><td>{merged}</td><td>{len(p["files"])} 文件</td></tr>'
sections.append(f'''<section id="journey" class="slide">{heading('03','HUMAN × AI / FOUR CONVERSATIONS','每一步都分清：AI 执行，我来判断。','沿四个会话展开八个关键步骤。逐项说明实际执行、我的决定，以及 AI 不能独立闭环的地方。')}<div class="collaboration-intro"><b>我的工作是收敛需求、追问方案、设定门槛，再体验与纠偏。</b><p>AI 完成了大量生成、实现、运行和审查工作；我没有把生成代码说成手写。“不能独立完成”指本次工作中仍需我的判断、外部条件或原始证据，不是泛称 AI 永远不会。</p></div><div class="timeline collaboration">{timeline}</div><div class="ownership-conclusion"><b>能自动执行，仍然要有签收依据。</b><p>另一 Agent 可以承担独立 review；产品体验由我实际检查，门禁由真实回执判定。地图授权、真机性能、真实服务与签名，需要相应外部条件，不能靠聊天里的成功声明补齐。</p></div><p class="source"><a href="collaboration.json">八步协作与原话索引 ↗</a> · 按会话建立时间排序；指令时间已核对原始会话，PR 合入记录来自 GitHub。当前工程证据对应第 06、08 节。</p><details><summary>展开已合入 PR 与提交证据 <span>6 PRs</span></summary><div class="table-wrap"><table><thead><tr><th>PR</th><th>内容</th><th>合入提交</th><th>北京时间</th><th>范围</th></tr></thead><tbody>{pr_rows}</tbody></table></div><p class="caption">文件数是 PR 变更范围，包含素材与证据，不等于业务代码量。PR #35 已关闭且未合入，大字号最终修复以 #37 为准。</p><a href="commit-show.txt">完整 git show --stat 输出</a> · <a href="history.json">PR 记录索引</a></details>{note('这一节重点讲我的工作，而不是代码行数。先讲两次具体纠偏：返回被误解后我明确入口规则；模拟器大字号看不懂后我要求返工。再讲两个控制：我按职能收敛 Agent，并设“工程不够 Harness 不准上”。AI 能承担执行与部分审查，范围、体验和外部证据要逐项签收。')}</section>''')
gallery=[('map-overview','地图工作台','站标、聚合、查询和直接同步。'),('stop-list','Browse stops','最近优先；查询与返回上下文。'),('delivery-detail','配送详情','地址与时间窗；终态操作入口。'),('failure-form','失败原因','预设原因；Other 必须有说明。'),('failure-record','离线失败记录','原因与记录时间、Waiting to sync。'),('completed-record','完成记录','本地结果与 Demo 确认时间。')]
