statuses={t['id']:t['status'] for t in work['tasks']}
task_rows=''.join(f'<tr><td><code>{t["id"]}</code></td><td>{e(t["title"])}</td><td>{e(", ".join(t["depends_on"]) or "起点")}</td><td>{tag("blocked" if statuses.get(t["id"])=="blocked" else "accepted", "warn" if statuses.get(t["id"])=="blocked" else "ok")}</td></tr>' for t in board['tasks'])
sections.append(f'''<section id="workflow" class="slide">{heading('06','SKILL × HARNESS','拆任务，也拆“谁能签收”。','Epic #14 的 19 项任务：16 项本地工作接受，3 项生产依赖保留 blocked。后续 #36 无障碍返工独立跟踪。')}<div class="workflow-path"><div><span>01</span><b>需求与合同</b><small>E00 → 明确接口 / 写域</small></div><div><span>02</span><b>装配与模块</b><small>E01 / E02 / E03 / E05 / E06 / E11</small></div><div><span>03</span><b>集成与验证</b><small>E04 / E07 / E08 + X00–X04</small></div><div><span>04</span><b>交付与边界</b><small>E10；E09 / X05 / E12 待证</small></div></div><p class="caption">上图按职责概括阶段；完整 depends_on 关系以下表及任务图为准。</p><div class="cards three">{card('SKILL','定义工作方式','需求、Issue、开发、测试、原生验收、性能、交付、主控与 Harness 共九个职能；每次按需加载。')}{card('HARNESS','执行、观察和拦截','候选指纹 / SDK 与依赖锁 / 资源 lease / 真实进程 / OS PNG / SQLite / 原始日志与 hash。')}{card('REVIEW','作者不自签修复','完成先进入 review，再独立审查；失败保留原件并进入 rework，旧证据不升级为新候选。')}</div><details><summary>展开实际依赖、任务状态与关闭标准 <span>19 TASKS</span></summary><div class="table-wrap"><table><thead><tr><th>ID</th><th>任务</th><th>依赖</th><th>执行板状态</th></tr></thead><tbody>{task_rows}</tbody></table></div></details><div class="boundary"><b>生产 no-go 仍然有效</b><p>E09 / #31 真机性能 · X05 / #32 远端强制发布门禁 · E12 / #33 真实服务、资源、签名与交付。面试预发布包不改变这些判定。</p></div><p class="source">{file_link('harness/project/backlog.json','依赖图')} · {file_link('harness/project/work.json','实际派工与审查记录')} · {file_link('harness/reports/readiness.md','Harness 审计')}。</p>{note('Skill 是规则和职能，Harness 是真正执行与拦截。准备好的 Skill 不代表 CI 已经强制，文档反例也不等于真机验证。这是我设“工程不达标不准上线”的具体实现。')}</section>''')
decisions=[
 ('存储','sqflite / SQLite','结果和 outbox 同一短事务；有约束和迁移。','SQL、映射与迁移手写。','Drift：查询变复杂或需要大量响应式读取；需要生成链和维护成本。'),
 ('状态','ChangeNotifier / Listenable','一个工作台，依赖少；构造注入便于替换。','订阅、dispose、异步完成归属显式管理。','Riverpod / Cubit：跨页共享、异步组合和团队复杂度显著提高时重新比较。'),
 ('同步','outbox + 串行发送','固定身份，恢复简单；匹配且持久 ACK 后出队。','多一张表与事务；吞吐受串行限制。','批量/并行：队列延迟实测影响业务，且服务端已定义幂等、部分失败和冲突协议。'),
 ('地图','flutter_map + 聚合','Flutter Widget 站标便于风格、语义与交互统一。','密集点性能、瓦片授权及内存需要验证。','原生/矢量：导航或完整离线成为核心需求，或实测渲染瓶颈出现。'),
 ('导航','类型化面板 + 来源','单工作台上下文、滚动和返回语义集中管理。','平台返回、Escape、焦点需专项测试。','go_router：独立页面、登录重定向或深链有实际需求时接入。'),
 ('分层','MVVM + Repository','UI、展示状态、一致性和 I/O 各有边界。','接口和生命周期管理增加少量代码。','domain / use case：复杂跨模块编排或重复规则值得抽取时引入。')]
decision_rows=''.join(f'<tr><td>{area}</td><td><b>{choice}</b><p>{benefit}</p></td><td>{cost}</td><td>{trigger}</td></tr>' for area,choice,benefit,cost,trigger in decisions)
sections.append(f'''<section id="decisions" class="slide">{heading('07','TRADE-OFFS','我选它，因为当前约束适合它。','收益、维护成本和重新评估条件一起讲；替代框架是比较对象，未实现的能力不写成已完成。')}<div class="table-wrap decisions"><table><thead><tr><th>领域</th><th>实际选择与理由</th><th>付出的代价</th><th>什么变化会让我重新选择</th></tr></thead><tbody>{decision_rows}</tbody></table></div><div class="strip"><div><b>业务离线 ≠ 完整离线地图</b><p>SQLite 是可靠业务记录；地图瓦片是可丢弃缓存。公共 OSM 瓦片不能用于离线预取或批量下载。</p></div><div><b>Flutter 框架的帮助与责任</b><p>SDK 提供 ChangeNotifier / Listenable；局部重建和对象释放仍由我的实现负责。</p></div></div><p class="source">依据：<a href="https://docs.flutter.dev/app-architecture/recommendations">Flutter 架构建议 ↗</a> · <a href="https://api.flutter.dev/flutter/foundation/ChangeNotifier-class.html">ChangeNotifier ↗</a> · <a href="https://pub.dev/packages/sqflite#transaction">sqflite 事务 ↗</a> · <a href="https://operations.osmfoundation.org/policies/tiles/">OSM 瓦片政策 ↗</a> · {file_link('docs/solution-design.md','项目选型报告')}。</p>{note('架构文档与当前代码均采用 ChangeNotifier。Riverpod/Cubit 从来是比较项，不要讲成“先用了 Riverpod 再迁移”。被追问更大应用时，讲变化条件，不要说某框架永远更好。')}</section>''')
sections.append(f'''<section id="evidence" class="slide">{heading('08','EVIDENCE & AI JUDGMENT','测试数字背后，是证据边界。','下面分层展示当前与历史事实；不会把旧候选的全量原生矩阵套给新的修复。')}<div class="evidence-stats"><div><b>196</b><span>Flutter host / widget</span></div><div><b>166</b><span>Harness · Linux CI 全通过</span></div><div><b>3</b><span>N7 实际配置</span></div><div><b>6</b><span>已合入 PR</span></div></div><div class="evidence-layers"><article><span>01 / 浏览器</span><b>原型 78 项 × 3 轮</b><p>HTML / Leaflet / localStorage 的交互证据，只证明原型。</p></article><article><span>02 / 当前代码基线</span><b>166 Harness + 196 Flutter</b><p>Darwin 165 通过 + 1 Linux 专属 N/A；Linux 166 通过。<a href="https://github.com/KuroGeo/transvirtual-driver-delivery/actions/runs/38148283089">bebda78 main CI 通过 ↗</a></p></article><article><span>03 / 定向原生修复</span><b>N7：两档最大字号 + 正常字号</b><p>iPhone 17 Pro 与 iPhone 16；实际 OS 字号、Reduce Motion、PNG、SQLite 和不同 PID。受控 fixture / 模拟确认。</p></article><article><span>04 / 历史与外部</span><b>全 34 项是旧候选；生产 no-go</b><p>PR34 原候选与当前 N7 分开；真机性能、真实服务、签名和远端强制门禁未补齐。</p></article></div><div class="cards two">{card('AI GOT THIS WRONG','大字信息裁切','实际最大 OS 字号截图暴露布局问题；PR37 改为完整安全区工作区与可展开摘要，保留普通布局、焦点和返回。')}{card('AI GOT THIS WRONG','Harness 错接受不完整结果','PR34 审查发现清理回执及截断 unittest 日志可被接受；用严格 PID / 进程组和完整 verbose 行数及反例修复。')}</div><div class="ownership"><b>AI 生成什么 / 我负责什么</b><p>Codex 生成 Flutter、测试、Harness 与文档；Oil UI 支持原型，图像生成工具制作图标。我给出产品方向、选择方案、纠正交互、检查模拟器、要求返工和设定门槛。未将生成代码宣称为手写。</p></div><p class="source">{file_link('harness/reports/large-text-repair.md','当前 N7 与 196/166 基线')} · {file_link('harness/reports/pr34-final-review.md','PR34 原始审查')} · <a href="ai-usage.md">AI 使用说明</a>。</p>{note('不要背测试数量当主论点。挑两条关键反例：outbox 插入失败必须整体回滚；错误 ACK 或确认写入失败必须保留队列。再解释用实际 PID 区分 OS 重启和 hot restart。')}</section>''')
demo=[('00:00','看清任务','展示地图/列表与状态筛选，进入 Offline。','初始 24 pending / 3 completed / 3 failed。'),('01:00','保存两个结果','完成一个 pending；另一个选失败原因或填写 Other。','两条结果本地提交，待同步计数 +2。'),('02:00','真正退出进程','终止后在同一安装重新启动，保留数据库。','结果、原因、Offline 和队列仍在。'),('03:00','回到 Online','观察 Demo 串行发送与匹配确认反馈。','确认事务落盘后，队列清空。'),('04:00','再启动与答辩','第三次启动不再重发；解释断网与确认写失败。','客户端保证保留和重试；服务端幂等需合同。')]
demo_rows=''.join(f'<article class="demo-step"><time>{t}</time><div><h3>{title}</h3><p>{action}</p><small>{expected}</small></div></article>' for t,title,action,expected in demo)
sections.append(f'''<section id="demo" class="slide">{heading('09','82-SECOND NATIVE DEMO','保存、重启、确认，直接看。','真实 iOS 模拟器录屏，配中文步骤与观察值。82 秒展示核心链路；可以边播放边讲。')}<figure class="demo-video"><video controls playsinline preload="metadata" poster="media/ocean-delivery-poster.webp" aria-label="Ocean Delivery 82 秒原生演示"><source src="media/ocean-delivery-demo.mp4" type="video/mp4">浏览器无法播放时，请<a href="media/ocean-delivery-demo.mp4">下载 MP4</a>。</video><figcaption><b>离线保存 2 条 → 系统进程重启 → 恢复 2 条 → 模拟确认 → 队列 0 → 第三次启动仍为 0</b><span>H.264 MP4 · 1080p · 历史构建实录 · 中文说明 · 无配音，便于现场讲解。</span></figcaption></figure><div class="video-evidence"><div><b>真实发生了什么</b><p>三个 OS 进程 <code>21377 → 21604 → 21697</code>；每次系统退出有回执，重启前后以只读快照和主机 SQLite 备份核对身份与结果。</p></div><div><b>这段视频的范围</b><p>使用 <code>workbench_entry.dart</code> 受控 Demo，界面操作通过 Flutter Driver；文字输入为 driver 模拟，确认来自本地 HTTP fixture。复用核验过的历史模拟器包，画面使用原题数据快照；当前公开 App 已换为自造合成 CSV。</p></div></div><p class="source"><a href="media/ocean-delivery-demo.mp4" download>下载压缩视频 ↗</a> · <a href="media/demo-proof.json">录制与压缩证据 ↗</a> · <a href="media/demo-transcript.md">讲解文字 ↗</a> · 仅裁去录制首尾等待，片内保留连续真实录屏；不扩大原有原生验收，也不代表真实后端或真机验证。</p><details class="live-demo-fallback"><summary>需要现场操作时：展开正式入口与 5 分钟备用路线</summary><div class="demo-layout"><div>{demo_rows}</div><div class="demo-panel"><p class="eyebrow">RUN / RESTART</p><h3>准确入口已写进 README</h3><pre><code>python3 harness/run.py pub
cd app
flutter run --target lib/main.dart \\
  --device-id "$OCEAN_DEMO_DEVICE" \\
  --dart-define=OCEAN_MODE=demo</code></pre><p>同设备的第二个终端：</p><pre><code>xcrun simctl terminate \\
  "$OCEAN_DEMO_DEVICE" \\
  dev.oceandelivery.oceanDelivery
xcrun simctl launch \\
  "$OCEAN_DEMO_DEVICE" \\
  dev.oceandelivery.oceanDelivery</code></pre><p class="caption">目标：Apple Silicon / iPhone 17 Pro / iOS 26.4。<br>终端中显式设置自己创建的设备 ID。Hot reload 不代替 OS 重启。</p><a href="{REPO}/blob/main/README.md">完整环境与运行命令 ↗</a></div></div></details><div class="pitch"><span>30-SECOND ENGLISH OPENING</span><p>“I built an offline-first delivery workbench. A delivery result and its pending event commit together in SQLite. After a real app restart, both remain intact. When I reconnect, the Demo sends queued events serially and removes each only after a matching confirmation is durably recorded.”</p></div>{note('先播 82 秒视频，跟着中文说明讲三件事：结果先可靠保存、真实新进程重开数据库、匹配确认持久化后才移除队列。把模拟确认与真实服务区别讲清楚。剩下时间重点讲第三节里的我的判断和两次纠偏。')}</section>''')
qas=[
 ('为什么 SQLite，而不是只用内存或偏好设置？','我需要把结果和队列原子提交，还要有条件更新、唯一身份和迁移。内存不能跨进程；多份键值记录需要我额外实现一致性。Drift 也能满足，但本范围的手写 SQL 更直接。'),
 ('Future 超时就取消了网络吗？','不会。Future.timeout 只结束等待，底层请求可能继续；当前逻辑不让迟到结果进入 ACK 提交。真实 HTTP Transport 还要处理取消/超时及服务端幂等。'),
 ('服务器收到结果，客户端来不及保存 ACK 呢？','保留原 outbox，下一进程用原 operationId 重试。服务端需要按操作身份幂等处理；客户端不能单独保证端到端恰好一次。'),
 ('ChangeNotifier 为什么够用，风险在哪里？','当前一个工作台；局部监听、不可变快照和构造注入简单。监听与 dispose 要显式管理，大异步依赖图会更难维护，届时重新评估 Riverpod/Cubit。'),
 ('一万个站点会怎么改？','先在真实工作负载下 profile 查询、排序、聚合、build/raster 与内存。增加索引/增量查询、可见区域站标与按需列表；实测 CPU 任务再移 isolate，不预先承诺当前性能。'),
 ('图片、签名和冲突怎么扩展？','附件文件与结果元数据分开，定义上传状态、恢复、限额、清理和账号归属。结果协议增加服务端版本与冲突类型；终态策略与人工处理先定合同。'),
 ('build、State、BuildContext 和 Key 怎么解释？','Widget 是配置，State 保存界面会话，BuildContext 表示树中的位置。build 应无 I/O 副作用；稳定 Key 帮助元素识别；控制器和订阅在 dispose 释放。'),
 ('debug 不卡，能说明上线性能吗？','不能。目标真机 profile 检查 UI/raster 慢帧、启动、内存与电池；release 复核实际体验。60Hz 单帧约16.7ms，高刷新率要按实际预算判断。')]
qa_html=''.join(f'<details class="qa"><summary>{q}<span>+</span></summary><p>{a}</p></details>' for q,a in qas)
sections.append(f'''<section id="review" class="slide">{heading('10','PROJECT Q&A','Q&A：实现与扩展','关于离线保存、同步确认、Flutter 实现和后续扩展的常见问题。')}<div class="review-intro">{tag('SQLite / Transaction')}{tag('Future / Lifecycle')}{tag('State / Rebuild')}{tag('Profile / Evidence')}</div><div class="qa-grid">{qa_html}</div><div class="roadmap"><div><span>NOW</span><b>可靠演示与本地结果</b><small>当前已实现</small></div><div><span>NEXT</span><b>服务合同与账号归属</b><small>幂等 / 冲突 / 权限</small></div><div><span>THEN</span><b>性能、附件与授权地图</b><small>真机 / 载荷 / 离线区域</small></div><div><span>LATER</span><b>路径与受控 Agent</b><small>先有业务能力和确认边界</small></div></div><p class="source">回答基于当前代码与 {file_link('docs/solution-design.md','演进设计')}；未来能力为规划，未声称已交付。</p>{note('先解释当前实现和验证结果，再说明未来方案的适用条件与需要补充的证据。')}</section>''')
