js='''const slides=[...document.querySelectorAll('.slide')];const links=[...document.querySelectorAll('nav a')];let current=0;let presenting=false;const mode=document.querySelector('#mode');const notes=document.querySelector('#notes');const counter=document.querySelector('#counter');const progress=document.querySelector('.progress');function updateLocaleLinks(){document.querySelectorAll('[data-locale]').forEach(a=>{const params=new URLSearchParams();if(presenting)params.set('present','1');if(document.body.classList.contains('notes-on'))params.set('notes','1');a.setAttribute('href',a.dataset.locale+(params.size?'?'+params:'')+'#'+slides[current].id);a.toggleAttribute('aria-current',a.lang===document.documentElement.lang);if(a.lang===document.documentElement.lang)a.setAttribute('aria-current','page')})}function show(i){current=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,n)=>s.classList.toggle('current',n===current));links.forEach((l,n)=>l.classList.toggle('active',n===current));counter.textContent=String(current+1).padStart(2,'0')+' / '+slides.length;document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===slides.length-1;progress.style.width=((current+1)/slides.length*100)+'%';updateLocaleLinks();if(presenting){window.scrollTo({top:0,behavior:'instant'});history.replaceState(null,'','#'+slides[current].id)}}mode.addEventListener('click',()=>{presenting=!presenting;document.body.classList.toggle('presenting',presenting);mode.setAttribute('aria-pressed',String(presenting));mode.textContent=presenting?'阅读模式':'演示模式';show(current);if(!presenting)slides[current].scrollIntoView()});notes.addEventListener('click',()=>{const on=document.body.classList.toggle('notes-on');notes.setAttribute('aria-pressed',String(on));notes.textContent=on?'隐藏讲述提示':'讲述提示';updateLocaleLinks()});document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.querySelector('#print').onclick=()=>window.print();document.addEventListener('keydown',e=>{if(!presenting||e.target.closest('button,a,summary,input,textarea,select,dialog'))return;if(['ArrowRight','ArrowDown','PageDown'].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Escape'){mode.click()}});document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const i=slides.findIndex(s=>s.id===a.getAttribute('href').slice(1));if(presenting&&i>=0){e.preventDefault();show(i)}}));const observer=new IntersectionObserver(items=>{if(presenting)return;const top=items.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(top)show(slides.indexOf(top.target))},{threshold:[.05,.2,.4,.7]});slides.forEach(s=>observer.observe(s));const dialog=document.querySelector('#image-dialog');document.querySelectorAll('.zoom-shot').forEach(b=>b.onclick=()=>{const src=b.querySelector('img');const dest=dialog.querySelector('img');dest.src=src.src;dest.alt=src.alt;dialog.showModal()});dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});const initial=slides.findIndex(s=>s.id===location.hash.slice(1));show(initial>=0?initial:0);if(initial>0)window.addEventListener('load',()=>{slides[initial].scrollIntoView({behavior:'instant',block:'start'});show(initial)},{once:true});const params=new URLSearchParams(location.search);if(params.get('present')==='1')mode.click();if(params.get('notes')==='1')notes.click();'''
